/*
 * name/test/test_name_data.c - the OLD_DIR data block NAME_$OLD_DIR_DATA
 * (SAU2 map "D E7FD24 OLD_DIR size = 4C0")
 *
 * Generated by: Claude Opus 5.5
 *
 * Proves, against the real definition in name/name_data.c:
 *   - every field sits at the A5 displacement the code uses and the block is
 *     the map's 0x4C0 bytes;
 *   - the two leaf sets carry the image bytes (`gsk read 0xE7FD24 0x40`) and
 *     the rest of the block is zero, as in the image;
 *   - a table indexed by pid N puts element N exactly where the assembly
 *     addresses it (displacement + N*stride), with the Pascal [1..64]
 *     element 1 right after the previous object;
 *   - the bias slots overlay the previous object's tail, which is what
 *     DIR_$OLD_INIT (0x00E314F4) relies on when it clears lock_uid[0..57].
 */

#include <stdio.h>
#include <string.h>
#include <stdint.h>

static int tests_passed = 0;
static int tests_failed = 0;
static int current_failed = 0;

#define TEST(name) static void test_##name(void)
#define RUN_TEST(name) do {                     \
    printf("  %-52s ", #name);                  \
    current_failed = 0;                         \
    test_##name();                              \
    if (current_failed) { tests_failed++; }     \
    else { tests_passed++; printf("PASSED\n"); }\
} while (0)

#define ASSERT_EQ(expected, actual) do {                                 \
    long long _e = (long long)(expected);                                \
    long long _a = (long long)(actual);                                  \
    if (_e != _a) {                                                      \
        printf("FAILED\n    Expected %lld, got %lld at line %d\n",       \
               _e, _a, __LINE__);                                        \
        current_failed = 1;                                              \
        return;                                                          \
    }                                                                    \
} while (0)

#include "dir/dir_internal.h"   /* DIR_$OLD_INIT, DIR_OLD_INIT_CLEAR_COUNT */
#include "name/name_internal.h"

#include "../name_data.c"
#include "../../dir/old_init.c"

/* Byte displacement of p from the block base, i.e. the A5 offset. */
#define A5_OFF(p) ((long)((const uint8_t *)(p) - (const uint8_t *)&NAME_$OLD_DIR_DATA))

static const uint8_t image_leaf_char_set[32] = {
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x7f, 0xff, 0xff, 0xff, 0xef, 0xff, 0xff, 0xff,
    0xff, 0xff, 0x7f, 0xfe, 0x00, 0x00, 0x00, 0x00
};

static const uint8_t image_leaf_first_char_set[32] = {
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x3f, 0xff, 0xff, 0xfe, 0xff, 0xff, 0xff, 0xff,
    0xff, 0xff, 0x3f, 0xfe, 0x00, 0x00, 0x00, 0x00
};

/* The map: D E7FD24 OLD_DIR size = 4C0. */
TEST(block_is_the_map_segment)
{
    ASSERT_EQ(0x00E7FD24, MODULE_DATA_ADDR(NAME_$OLD_DIR_DATA));
    ASSERT_EQ(0x4C0, sizeof(NAME_$OLD_DIR_DATA));
    ASSERT_EQ(0x00E801E4, MODULE_DATA_ADDR(NAME_$OLD_DIR_DATA) + NAME_$OLD_DIR_DATA_SIZE);
}

TEST(field_offsets_match_a5_displacements)
{
    ASSERT_EQ(0x000, A5_OFF(NAME_$OLD_DIR_DATA.leaf_char_set));        /* lea (A5),A0      0x00E54492 */
    ASSERT_EQ(0x020, A5_OFF(NAME_$OLD_DIR_DATA.leaf_first_char_set));  /* lea (0x20,A5),A0 0x00E5446E */
    ASSERT_EQ(0x03C, A5_OFF(NAME_$OLD_DIR_DATA.lock_slot));            /* (0x3c,A5,D6w)    0x00E548AC */
    ASSERT_EQ(0x13E, A5_OFF(NAME_$OLD_DIR_DATA.lock_mode));            /* (0x13e,A0)       0x00E54894 */
    ASSERT_EQ(0x1BC, A5_OFF(NAME_$OLD_DIR_DATA.lock_handle));          /* (0x1bc,A0)       0x00E548A0 */
    ASSERT_EQ(0x2B8, A5_OFF(NAME_$OLD_DIR_DATA.lock_uid));             /* (0x2b8,A0)       0x00E548EA */
}

TEST(image_contents)
{
    const uint8_t *b = (const uint8_t *)&NAME_$OLD_DIR_DATA;
    int i;

    ASSERT_EQ(0, memcmp(NAME_$OLD_DIR_DATA.leaf_char_set, image_leaf_char_set, 32));
    ASSERT_EQ(0, memcmp(NAME_$OLD_DIR_DATA.leaf_first_char_set, image_leaf_first_char_set, 32));
    for (i = 0x40; i < 0x4C0; i++) {
        ASSERT_EQ(0, b[i]);
    }
}

/*
 * The assembly forms each element's address as displacement + pid*stride:
 *   slot   lsl.w #2 / (0x3c,A5,D6w)      0x00E5489A, 0x00E548AC
 *   mode   add.w D0,D0 / (0x13e,A0)      0x00E5488E, 0x00E54894
 *   handle lsl.w #2 / (0x1bc,A0)         0x00E5489A, 0x00E548A0
 *   uid    lsl.w #3 / (0x2b8,A0)         0x00E548E4, 0x00E548EA
 * so pid N's entry is element N of each table, for every pid 1..64.
 */
TEST(pid_n_lands_in_element_n)
{
    int pid;

    for (pid = 1; pid <= 64; pid++) {
        ASSERT_EQ(0x3C + pid * 4, A5_OFF(&NAME_$OLD_DIR_DATA.lock_slot[pid]));
        ASSERT_EQ(0x13E + pid * 2, A5_OFF(&NAME_$OLD_DIR_DATA.lock_mode[pid]));
        ASSERT_EQ(0x1BC + pid * 4, A5_OFF(&NAME_$OLD_DIR_DATA.lock_handle[pid]));
        ASSERT_EQ(0x2B8 + pid * 8, A5_OFF(&NAME_$OLD_DIR_DATA.lock_uid[pid]));
    }
}

/* Pascal [1..64]: element 1 follows the previous object and element 64
 * ends where the next begins. */
TEST(pascal_tables_tile_the_block)
{
    ASSERT_EQ(0x040, A5_OFF(&NAME_$OLD_DIR_DATA.lock_slot[1]));
    ASSERT_EQ(0x140, A5_OFF(&NAME_$OLD_DIR_DATA.lock_slot[64]) + 4);
    ASSERT_EQ(0x140, A5_OFF(&NAME_$OLD_DIR_DATA.lock_mode[1]));
    ASSERT_EQ(0x1C0, A5_OFF(&NAME_$OLD_DIR_DATA.lock_mode[64]) + 2);
    ASSERT_EQ(0x1C0, A5_OFF(&NAME_$OLD_DIR_DATA.lock_handle[1]));
    ASSERT_EQ(0x2C0, A5_OFF(&NAME_$OLD_DIR_DATA.lock_handle[64]) + 4);
    ASSERT_EQ(0x2C0, A5_OFF(&NAME_$OLD_DIR_DATA.lock_uid[1]));
    ASSERT_EQ(0x4C0, A5_OFF(&NAME_$OLD_DIR_DATA.lock_uid[64]) + 8);
}

/* A lock recorded for pid N (as NAME_$LOCK_DIR stores it) touches only
 * element N of each table and leaves pid N-1 / N+1 alone. */
TEST(pid_entries_are_independent)
{
    uid_t u = { 0x11223344u, 0x55667788u };
    const int pid = 7;

    NAME_$OLD_DIR_DATA.lock_mode[pid] = 4;
    NAME_$OLD_DIR_DATA.lock_handle[pid] = 0x00123000u;
    NAME_$OLD_DIR_DATA.lock_slot[pid] = 0xCAFE0001u;
    NAME_$OLD_DIR_DATA.lock_uid[pid] = u;

    ASSERT_EQ(4, NAME_$OLD_DIR_DATA.lock_mode[pid]);
    ASSERT_EQ(0x00123000u, NAME_$OLD_DIR_DATA.lock_handle[pid]);
    ASSERT_EQ(0xCAFE0001u, NAME_$OLD_DIR_DATA.lock_slot[pid]);
    ASSERT_EQ(0x11223344u, NAME_$OLD_DIR_DATA.lock_uid[pid].high);
    ASSERT_EQ(0x55667788u, NAME_$OLD_DIR_DATA.lock_uid[pid].low);
    ASSERT_EQ(0, NAME_$OLD_DIR_DATA.lock_mode[pid - 1]);
    ASSERT_EQ(0, NAME_$OLD_DIR_DATA.lock_mode[pid + 1]);
    ASSERT_EQ(0, NAME_$OLD_DIR_DATA.lock_handle[pid + 1]);
    ASSERT_EQ(0, NAME_$OLD_DIR_DATA.lock_slot[pid + 1]);
    ASSERT_EQ(0, NAME_$OLD_DIR_DATA.lock_uid[pid + 1].high);

    NAME_$OLD_DIR_DATA.lock_mode[pid] = 0;
    NAME_$OLD_DIR_DATA.lock_handle[pid] = 0;
    NAME_$OLD_DIR_DATA.lock_slot[pid] = 0;
    memset(&NAME_$OLD_DIR_DATA.lock_uid[pid], 0, sizeof(uid_t));
}

/* The bias slots overlay the previous object's tail (name/name.h). */
TEST(bias_slots_overlay_previous_object)
{
    ASSERT_EQ(A5_OFF(&NAME_$OLD_DIR_DATA.leaf_first_char_set[28]),
              A5_OFF(&NAME_$OLD_DIR_DATA.lock_slot[0]));
    ASSERT_EQ(A5_OFF(&NAME_$OLD_DIR_DATA.lock_slot[64]) + 2,
              A5_OFF(&NAME_$OLD_DIR_DATA.lock_mode[0]));
    ASSERT_EQ(A5_OFF(&NAME_$OLD_DIR_DATA.lock_mode[63]),
              A5_OFF(&NAME_$OLD_DIR_DATA.lock_handle[0]));
    ASSERT_EQ(A5_OFF(&NAME_$OLD_DIR_DATA.lock_handle[63]),
              A5_OFF(&NAME_$OLD_DIR_DATA.lock_uid[0]));
}

/*
 * DIR_$OLD_INIT: `movea.l #0xe7fd24,A0` + 58 x `clr.l (0x2b8,A0)` /
 * `addq.l #8,A0` clears lock_uid[0..57].high.  Index 0 is the bias slot, so
 * the first clear lands on lock_handle[63]; lock_uid[58..64] survive.
 */
TEST(old_init_clears_uid_0_through_57)
{
    int i;

    for (i = 0; i <= 64; i++) {
        NAME_$OLD_DIR_DATA.lock_uid[i].high = 0xA5A5A5A5u;
        NAME_$OLD_DIR_DATA.lock_uid[i].low = 0x5A5A5A5Au;
    }
    NAME_$OLD_DIR_DATA.lock_handle[62] = 0x62626262u;

    DIR_$OLD_INIT();

    for (i = 0; i <= 57; i++) {
        ASSERT_EQ(0, NAME_$OLD_DIR_DATA.lock_uid[i].high);
        ASSERT_EQ(0x5A5A5A5Au, NAME_$OLD_DIR_DATA.lock_uid[i].low);
    }
    for (i = 58; i <= 64; i++) {
        ASSERT_EQ(0xA5A5A5A5u, NAME_$OLD_DIR_DATA.lock_uid[i].high);
    }
    ASSERT_EQ(0, NAME_$OLD_DIR_DATA.lock_handle[63]);          /* = lock_uid[0].high */
    ASSERT_EQ(0x5A5A5A5Au, NAME_$OLD_DIR_DATA.lock_handle[64]); /* = lock_uid[0].low */
    ASSERT_EQ(0x62626262u, NAME_$OLD_DIR_DATA.lock_handle[62]);

    memset(NAME_$OLD_DIR_DATA.lock_uid, 0, sizeof(NAME_$OLD_DIR_DATA.lock_uid));
    NAME_$OLD_DIR_DATA.lock_handle[62] = 0;
}

int main(void)
{
    printf("NAME_$OLD_DIR_DATA (OLD_DIR block, 0x00E7FD24) tests\n");
    RUN_TEST(block_is_the_map_segment);
    RUN_TEST(field_offsets_match_a5_displacements);
    RUN_TEST(image_contents);
    RUN_TEST(pid_n_lands_in_element_n);
    RUN_TEST(pascal_tables_tile_the_block);
    RUN_TEST(pid_entries_are_independent);
    RUN_TEST(bias_slots_overlay_previous_object);
    RUN_TEST(old_init_clears_uid_0_through_57);
    printf("\n%d passed, %d failed\n", tests_passed, tests_failed);
    return tests_failed ? 1 : 0;
}
